<?php
declare(strict_types=1);
namespace App\Application\Review\Service;
use App\Application\Review\DTO\Request\CreateOrReuseFlashcardRequestDto;use App\Domain\Review\Entity\Flashcard;use App\Domain\Review\Enum\FlashcardType;use App\Domain\Review\Repository\FlashcardRepositoryInterface;use App\Domain\Review\ValueObject\FlashcardFingerprint;use App\Domain\Taxonomy\Repository\TaxonomySubjectRepositoryInterface;
final readonly class CreateOrReuseFlashcardService { public function __construct(private FlashcardRepositoryInterface $cards,private TaxonomySubjectRepositoryInterface $subjects){} public function execute(CreateOrReuseFlashcardRequestDto $request,\DateTimeImmutable $now):Flashcard { $subject=$this->subjects->findById($request->taxonomySubjectId);if($subject===null||!$subject->active)throw new \DomainException('Assunto canônico indisponível.');$fingerprint=FlashcardFingerprint::fromContent($subject->id,FlashcardType::BASIC,$request->front,$request->back);$existing=$this->cards->findByFingerprint($subject->id,$fingerprint);if($existing!==null)return $existing;$card=new Flashcard($this->uuid(),$subject->id,FlashcardType::BASIC,trim($request->front),trim($request->back),$fingerprint,$request->source,$now,$now,[$subject->id]);$this->cards->save($card);return $card;} private function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));} }
